// Названия разделов (переименованы 01.10.2026 по просьбе коллег). В тексте их
// не склоняем: «в разделе «Аудит отзывов»», а не «в «Аудите отзывов»».
// was — прежнее имя: его называет разовая заметка о переименовании (до RENAMED_UNTIL).
// Порядок — как попросило руководство (аудит первым). Вход в приложение и логотип
// всё равно ведут на «Новостные обзоры»: с выпуска начинается 85% рабочих дней.
// «Рынок · позиция» — режим «Новостных обзоров» (OvSeg), группа «Данные» свёрнута.
const NAV = [{
  id: "reviews",
  label: "Аудит отзывов",
  icon: Ic.msg,
  group: "Анализ",
  was: "Отзывы"
}, {
  id: "loophole",
  label: "Аудит уязвимостей",
  icon: Ic.shield,
  group: "Анализ",
  was: "Уязвимости"
}, {
  id: "overview",
  label: "Новостные обзоры",
  icon: Ic.news,
  group: "Анализ",
  was: "Обзор"
}, {
  id: "ai",
  label: "ИИ-помощник",
  icon: Ic.spark,
  group: "Анализ",
  was: "ИИ-аналитик"
}, {
  id: "knowledge",
  label: "База знаний",
  icon: Ic.src,
  group: "Данные"
}, {
  id: "banks",
  label: "Банки",
  icon: Ic.bank,
  group: "Данные"
}, {
  id: "sources",
  label: "Источники",
  icon: Ic.src,
  group: "Данные"
}];
// режимы внутри разделов: в меню подсвечивается раздел, в крошке — его номер и имя
const SECTION_OF = {
  foryou: "overview",
  market: "overview",
  sber: "overview"
};
const DATA_IDS = new Set(["knowledge", "banks", "sources", "pulse"]);
const PAGES_FN = {
  overview: OverviewPage,
  foryou: ForYouPage,
  market: MarketPage,
  sber: SberPage,
  reviews: ReviewsPage,
  ai: AIPage,
  knowledge: KnowledgePage,
  loophole: LoopholePage,
  banks: BanksPage,
  sources: SourcesPage,
  profile: ProfilePage,
  pulse: PulsePage,
  vsp: VspPage
};
// Номера синхронизированы с порядком в меню; итог берётся из NAV, а не хардкодом
// Названия разделов для крошки в шапке. Номер берётся из порядка меню (navOrder),
// а не пишется здесь: захардкоженные номера разошлись с меню после перестановки
// вкладок («Уязвимости» в меню 05, в шапке было 06).
const PAGE_LABELS = {
  overview: "Новостные обзоры",
  foryou: "Для вас",
  market: "Рынок · позиция",
  sber: "Рынок · позиция",
  reviews: "Аудит отзывов",
  ai: "ИИ-помощник",
  knowledge: "База знаний",
  loophole: "Аудит уязвимостей",
  banks: "Банки",
  sources: "Источники",
  profile: "Профиль",
  pulse: "Пульс",
  vsp: "Аудит сети ВСП"
};
// до этой даты в меню показывается заметка о переименовании (пока её не закрыли)
const RENAMED_UNTIL = "2026-10-15";
const renamedFresh = () => new Date().toISOString().slice(0, 10) <= RENAMED_UNTIL;
// Когда показывать приглашение подключить почту: 1 — ещё не показывали, 2 — первый
// раз закрыли «Не сейчас» неделю назад или раньше, 0 — не показывать. Даты отказа
// у первых показов (до 06.10) нет — считаем от 06.10.
const MAIL_PROMO_AGAIN_DAYS = 7;
const mailPromoDue = prefs => {
  const v = prefs && prefs.mail_promo;
  if (!v) return 1;
  if (v !== "seen") return 0;
  const at = Date.parse((prefs.mail_promo_at || "2026-10-06") + "T00:00:00");
  return Date.now() - at >= MAIL_PROMO_AGAIN_DAYS * 864e5 ? 2 : 0;
};

