// Любая ошибка рендера страницы → заглушка с кнопкой вместо белого экрана,
// ошибка уходит в журнал «Пульса» (kind=client_error) даже если трекер страницы мёртв.
function journalRenderError(e, info, where) {
  try {
    fetch("/api/journal", {
      method: "POST",
      headers: {
        "Content-Type": "application/json"
      },
      body: JSON.stringify({
        events: [{
          kind: "client_error",
          page: (location.hash || "#").slice(1),
          payload: {
            msg: String(e && e.message || e).slice(0, 300),
            where: where || null,
            stack: String(info && info.componentStack || "").slice(0, 400)
          }
        }]
      })
    }).catch(() => {});
  } catch {}
}

